#!/bin/bash
# Copyright Allo authors. All Rights Reserved.
# SPDX-License-Identifier: Apache-2.0
# usage: run_tb.sh <minitpu-tree> <prj> <tb.sv> <build-dir> [extra verilator args]
# Builds <tb.sv> (a MiniTPU tb, or the record's measuring copy) with mxu_allo.sv (generated by gen_mxu_vhls.py
# from <prj>) in place of src/core/mxu/mxu.sv and the Vitis HLS RTL (<prj>/out.prj/solution1/syn/verilog/*.v)
# as the core; the unit suite's flags (verilator --binary --timing). The MiniTPU tree is only read.
set -euo pipefail
T=$1; P=$2; TBF=$(readlink -f "$3"); B=$4; shift 4
TB=$(basename "$TBF" .sv)
D=$(cd "$(dirname "$0")" && pwd)
mkdir -p "$B"
python3 "$D/gen_mxu_vhls.py" "$P" "$B/mxu_allo.sv" ${FIFO_DEPTH:+--fifo-depth $FIFO_DEPTH}
V=$P/out.prj/solution1/syn/verilog
cd "$T"
verilator --build-jobs 8 --binary --timing -Wno-fatal --top-module "$TB" \
  src/core/vpu/vpu_pkg.sv "$B/mxu_allo.sv" "$V"/*.v "$TBF" --Mdir "$B/obj_$TB" "$@" > "$B/verilator_$TB.log" 2>&1 \
  || { tail -30 "$B/verilator_$TB.log"; exit 1; }
timeout "${TB_TIMEOUT:-600}" "$B/obj_$TB/V$TB"
